package me.matsumo.fanbox.core.logs.category

import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put

// This class is automatically generated by generate-log-classes.
sealed interface BillingLog : LogCategory {

    class PaywallShown internal constructor(
        referrer: String,
        initialPlan: String,
        isPlanLoaded: Boolean,
        daysSinceFirstLaunch: Int,
    ) : BillingLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "billing")
            put("event_name", "paywall_shown")
            put("referrer", referrer)
            put("initial_plan", initialPlan)
            put("is_plan_loaded", isPlanLoaded)
            put("days_since_first_launch", daysSinceFirstLaunch)
        }
    }

    class PaywallPlanSelected internal constructor(referrer: String, plan: String) : BillingLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "billing")
            put("event_name", "paywall_plan_selected")
            put("referrer", referrer)
            put("plan", plan)
        }
    }

    class PurchaseStarted internal constructor(
        referrer: String,
        plan: String,
        hasTrial: Boolean,
    ) : BillingLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "billing")
            put("event_name", "purchase_started")
            put("referrer", referrer)
            put("plan", plan)
            put("has_trial", hasTrial)
        }
    }

    class PurchaseSucceeded internal constructor(
        referrer: String,
        plan: String,
        hasTrial: Boolean,
    ) : BillingLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "billing")
            put("event_name", "purchase_succeeded")
            put("referrer", referrer)
            put("plan", plan)
            put("has_trial", hasTrial)
        }
    }

    class PurchaseCancelled internal constructor(referrer: String, plan: String) : BillingLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "billing")
            put("event_name", "purchase_cancelled")
            put("referrer", referrer)
            put("plan", plan)
        }
    }

    class PurchaseFailed internal constructor(
        referrer: String,
        plan: String,
        errorType: String,
    ) : BillingLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "billing")
            put("event_name", "purchase_failed")
            put("referrer", referrer)
            put("plan", plan)
            put("error_type", errorType)
        }
    }

    class PaywallDismissed internal constructor(referrer: String, lastPurchaseResult: String) : BillingLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "billing")
            put("event_name", "paywall_dismissed")
            put("referrer", referrer)
            put("last_purchase_result", lastPurchaseResult)
        }
    }

    class RetentionPromptShown internal constructor(
        planType: String,
        unsubscribeDetectedAtMillis: Long?,
        isAnnualOfferShown: Boolean,
    ) : BillingLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "billing")
            put("event_name", "retention_prompt_shown")
            put("plan_type", planType)
            put("unsubscribe_detected_at_millis", unsubscribeDetectedAtMillis)
            put("is_annual_offer_shown", isAnnualOfferShown)
        }
    }

    class RetentionPromptAnnualClicked internal constructor() : BillingLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "billing")
            put("event_name", "retention_prompt_annual_clicked")
        }
    }

    class RetentionPromptManageClicked internal constructor(platform: String) : BillingLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "billing")
            put("event_name", "retention_prompt_manage_clicked")
            put("platform", platform)
        }
    }

    class RetentionPromptDismissed internal constructor(reason: String) : BillingLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "billing")
            put("event_name", "retention_prompt_dismissed")
            put("reason", reason)
        }
    }

    companion object {
        // Plus 課金画面を開き、プランの取得が終わったときのログ。課金画面を 1 回開くごとに 1 回送る
        fun paywallShown(
            referrer: String,
            initialPlan: String,
            isPlanLoaded: Boolean,
            daysSinceFirstLaunch: Int,
        ) = PaywallShown(referrer, initialPlan, isPlanLoaded, daysSinceFirstLaunch)

        // 課金画面でプランを選び直したときのログ。選択中と同じプランを選んだときは送らない
        fun paywallPlanSelected(referrer: String, plan: String) = PaywallPlanSelected(referrer, plan)

        // 購入ボタンを押し、ストアの購入処理を開始したときのログ。購入処理の完了までは次の購入を開始しない
        fun purchaseStarted(
            referrer: String,
            plan: String,
            hasTrial: Boolean,
        ) = PurchaseStarted(referrer, plan, hasTrial)

        // 購入が成立し、Plus が有効になったときのログ
        fun purchaseSucceeded(
            referrer: String,
            plan: String,
            hasTrial: Boolean,
        ) = PurchaseSucceeded(referrer, plan, hasTrial)

        // ユーザーがストアの購入画面で購入をキャンセルしたときのログ
        fun purchaseCancelled(referrer: String, plan: String) = PurchaseCancelled(referrer, plan)

        // キャンセル以外の理由で購入が成立しなかったときのログ
        fun purchaseFailed(
            referrer: String,
            plan: String,
            errorType: String,
        ) = PurchaseFailed(referrer, plan, errorType)

        // 購入が成立しないまま課金画面を閉じたときのログ。購入が成立したときは送らない
        fun paywallDismissed(referrer: String, lastPurchaseResult: String) = PaywallDismissed(referrer, lastPurchaseResult)

        // リテンション UI 表示
        fun retentionPromptShown(
            planType: String,
            unsubscribeDetectedAtMillis: Long?,
            isAnnualOfferShown: Boolean,
        ) = RetentionPromptShown(planType, unsubscribeDetectedAtMillis, isAnnualOfferShown)

        // リテンション UI 年額 CTA
        fun retentionPromptAnnualClicked() = RetentionPromptAnnualClicked()

        // リテンション UI 購読管理 CTA
        fun retentionPromptManageClicked(platform: String) = RetentionPromptManageClicked(platform)

        // リテンション UI dismiss
        fun retentionPromptDismissed(reason: String) = RetentionPromptDismissed(reason)
    }
}
